'use client';import {useParams,useRouter} from 'next/navigation';import {useEffect,useState} from 'react';
const labels:any={closeness:'Эмоциональная близость',communication:'Общение',conflict:'Конфликты',money:'Деньги',daily:'Быт',space:'Личное пространство',intimacy:'Близость',future:'Будущее',understanding:'Понимание друг друга'};
export default function Result(){const{coupleId}=useParams<{coupleId:string}>();const[d,setD]=useState<any>();const r=useRouter();useEffect(()=>{fetch(`/api/report?id=${coupleId}`).then(x=>x.json()).then(x=>x.waiting?r.push(`/waiting/${coupleId}`):setD(x))},[coupleId,r]);if(!d)return <main className="shell"><section className="hero center"><p>Сравниваем ваши ответы…</p></section></main>;const entries=Object.entries(d.scores as Record<string,number>);const best=[...entries].sort((a,b)=>b[1]-a[1])[0];const low=[...entries].sort((a,b)=>a[1]-b[1])[0];return <main className="shell"><div className="brand">между нами</div><h1 className="h1" style={{fontSize:48}}>{d.couple.partner_a_name} + {d.couple.partner_b_name}</h1><p className="lead">Вот как похоже вы воспринимаете разные стороны ваших отношений.</p>{entries.map(([k,v])=><div className="scoreRow" key={k}><div className="scoreHead"><span>{labels[k]}</span><b>{v}%</b></div><div className="bar"><div style={{width:`${v}%`}}/></div></div>)}<div className="card"><div className="eyebrow">особенно близко</div><h2>{labels[best[0]]}</h2><p>В этой теме ваши ответы совпадают сильнее всего.</p></div><div className="card"><div className="eyebrow">вы видите это по-разному</div><h2>{labels[low[0]]}</h2><p>Здесь разница в восприятии заметнее. Это не означает, что кто-то из вас неправ.</p></div><div className="card"><h2>Мы нашли ещё несколько важных вещей</h2><div className="locked"><p>Чего каждый из вас ждёт от другого</p><p>Где вы неверно угадываете потребности партнёра</p><p>5 вопросов специально для вашей пары</p></div><button className="btn" onClick={()=>r.push(`/report/${coupleId}`)}>Открыть полный разбор — 299 ₽</button></div></main>}
